Q: Export HTML table data to Excel using JavaScript / jQuery is not working properly in Chrome browser A: <p>An Excel export script that works on <a href="https://en.wikipedia.org/wiki/Internet_Explorer_7" rel="nofollow noreferrer">Internet Explorer 7</a> or later, Firefox and Chrome:</p>
<pre><code>function fnExcelReport()
{
    var tab_text = &quot;&lt;table border='2px'&gt;&lt;tr bgcolor='#87AFC6'&gt;&quot;;
    var textRange;
    var j = 0;
    tab = document.getElementById('headerTable'); // id of the table

    for(j = 0; j &lt; tab.rows.length; j++)
    {
        tab_text = tab_text + tab.rows[j].innerHTML + &quot;&lt;/tr&gt;&quot;;
        //tab_text = tab_text + &quot;&lt;/tr&gt;&quot;;
    }

    tab_text = tab_text + &quot;&lt;/table&gt;&quot;;
    tab_text = tab_text.replace(/&lt;A[^&gt;]*&gt;|&lt;\/A&gt;/g, &quot;&quot;); // Remove if u want links in your table
    tab_text = tab_text.replace(/&lt;img[^&gt;]*&gt;/gi,&quot;&quot;); // Remove if u want images in your table
    tab_text = tab_text.replace(/&lt;input[^&gt;]*&gt;|&lt;\/input&gt;/gi, &quot;&quot;); // Reomves input params

    var ua = window.navigator.userAgent;
    var msie = ua.indexOf(&quot;MSIE &quot;);

    if (msie &gt; 0 || !!navigator.userAgent.match(/Trident.*rv\:11\./)) // If Internet Explorer
    {
        txtArea1.document.open(&quot;txt/html&quot;, &quot;replace&quot;);
        txtArea1.document.write(tab_text);
        txtArea1.document.close();
        txtArea1.focus();
        sa = txtArea1.document.execCommand(&quot;SaveAs&quot;, true, &quot;Say Thanks to Sumit.xls&quot;);
    }
    else // Other browsers not tested on Internet Explorer 11
        sa = window.open('data:application/vnd.ms-excel,' + encodeURIComponent(tab_text));

    return (sa);
}
</code></pre>
<p>Just create a blank iframe:</p>
<pre><code>&lt;iframe id=&quot;txtArea1&quot; style=&quot;display:none&quot;&gt;&lt;/iframe&gt;
</code></pre>
<p>Call this function on:</p>
<pre><code>&lt;button id=&quot;btnExport&quot; onclick=&quot;fnExcelReport();&quot;&gt; EXPORT &lt;/button&gt;
</code></pre>
